from pathlib import Path
import json
p=Path(__file__).resolve().parents[1]/'data/buildings.json'; data=json.loads(p.read_text()); by={x['slug']:x for x in data}
rows={
'gipersfera':([('https://zombie-island.moy.su/blog/gipersfera_za_golosa/2014-01-10-2628','Zombie-island: Гиперсфера за голоса')],{'Вариант за голоса':'Статья указывает 1-й уровень, цену 25 голосов, продажу за 250 000 монет, 100 опыта за покупку и 700 всего. Стадия 1: 50 металла, 15 простыней, 10 Зомби-оскаров (150 опыта); стадия 2: 30 фольги, 10 огненных обручей, 3 метеорита (200 опыта); стадия 3: 25 лампочек, 15 цирковых шаров, 15 кинолент (250 опыта).','Назначение':'Позволяет крутить рулетки на том же острове, выбирая каждую отдельно; статья не утверждает, что все вращения происходят одним действием. Вариант за голоса не следует автоматически приравнивать к варианту за зомбаксы.'}),
'emchu-ina-vostoka':([('https://zombie-island.moy.su/blog/zhemchuzhina_vostoka_postrojka_zombie_farm_mania/2014-10-02-3217','Zombie-island: вариант за голоса'),('https://zombie-island.moy.su/blog/zhemchuzhina_vostoka_postrojka_zombie_farm_mania/2014-10-02-3218','Zombie-island: вариант за зомбаксы')],{'Назначение':'Открывает сразу много однотипных ценностей и отправляет содержимое на склад. Обе статьи указывают уровень 70, продажу за 230 000 монет, 100 опыта за покупку и 700 всего.','Вариант за 23 голоса':'Стадия 1: 40 стали, 10 кинолент, 15 огненных обручей; стадия 2: 30 лампочек, 3 бигуди, 15 шёлка; стадия 3: 38 вёдер, 5 чёрных сердец, 13 пенопласта.','Вариант за 230 зомбаксов':'Стадия 1: 50 стали, 15 кинолент, 20 огненных обручей; стадия 2: 55 лампочек, 5 бигуди, 20 шёлка; стадия 3: 59 вёдер, 12 чёрных сердец, 23 пенопласта. Два варианта имеют разные рецепты и не должны смешиваться.'}),
'derevo-mira':([('https://zombie-island.moy.su/blog/derevo_mira_zombie_farm_mania/2015-04-30-3592','Zombie-island: Дерево мира, стадии и рулетка'),('https://zombie-island.moy.su/blog/dekoracija_derevo_mira_zombie_mania_farm/2015-04-30-3593','Zombie-island: одноимённая декорация')],{'История и разногласие':'По Zombie-island, появилось 30 апреля 2015 года и было доступно на рынке несколько дней, только на Домашнем острове; цена 700 000 монет, продажа 70 000, покупка даёт 50 опыта. Значок уровня в этой статье — 7; отдельная карточка ZOMBIA указывает уровень 0. Причина расхождения неизвестна.','Рулетка и декорация':'После одного вращения постройка превращается в одноимённую декорацию; после вращения статья описывает возможность купить следующее дерево. Среди возможных призов Голуби и рулеточные зомби. Вероятности не приведены.','Опыт и стадии':'Восемь стадий в ZOMBIA и Zombie-island совпадают; перечислены в предыдущей записи. Сумма указанного опыта за стадии — 2450; ещё 50 за покупку дают 2500. Это объясняет запись ZOMBIA «2500» рядом с суммой стадий.'})}
for slug,(sources,fields) in rows.items():
 x=by[slug]; rid='elite-tree-verified-'+slug
 for url,label in sources:
  if not any(s['url']==url for s in x['sources']):x['sources'].append({'url':url,'label':label})
 if slug=='derevo-mira':
  for s in x['sources']:
   if s['url']=='https://zombi.at.ua/board/postrojki/ruletki/derevo_mira/33-1-0-1159':s['label']='ZOMBIA: отдельная карточка, размещена 30.04.2015'
 if not any(r.get('original_id')==rid for r in x['prior_records']):x['prior_records'].append({'original_id':rid,'original_category':'Проверенные исторические статьи','version':'браузерная игра; варианты и времена могут отличаться','date':'дата в адресе статьи; позднейшие правки не исключены','fields':fields,'confidence':'Фанатские источники; сходство сведений не гарантирует независимость. Для уровня Дерева мира источники расходятся.' if slug=='derevo-mira' else 'Фанатские исторические статьи; не переносить стоимость и рецепты между вариантами автоматически.'})
